const daily=[];
daily.push(`# ${date} 今日申论好文与金句积累\n\n> 今日主题：公共服务、公安交通与未成年人保护、生态系统治理、开源创新、人工智能责任。5篇精读来自人民日报、新华社、光明日报与半月谈；其中半月谈使用已核验的光明网转载。本文解释、标题、G表达、迁移示范和练习均为原创，非报刊原文或官方考试答案。\n\n## 一、今日精读好文（5篇）`);
for(const [i,a] of articles.entries()){const s=source(a.id);daily.push(`### ${i+1}. ${a.id==='daily-police-20261105'?'★★【公安岗重点】★★ ':''}${s.title}\n\n- **完整出处：** ${s.publisher}，${s.publishedAt}；[原文页面](${s.url})。核验日期：${date}。\n- **主旨：** ${a.summary}\n- **关键素材：** ${a.facts}\n- **申论价值（原创）：** ${a.method}\n- **可迁移方向：** ${a.themes}。\n- **使用边界：** ${a.boundary}\n- **原创迁移示范：** ${a.transfer}\n- **读后主动回忆：** ${a.question}`);}
daily.push(`## 二、今日原创申论标题（8个）\n\n1. 让有限空间承载更好的公共服务\n2. 从一次处置走向持续守护\n3. 把便民入口留给每一种需要\n4. 以系统思维守护一河安澜\n5. 让开放创新与责任安排同行\n6. 在技术向前时把纠错通道留下\n7. 用真实体验检验服务成色\n8. 既把问题解决好 也把责任接续好\n\n## 三、原创迁移金句（15条；G1041—G1055）`);
for(const group of ['开头句','分论点句','过渡句','对策句','结尾句'])daily.push(`### ${group}\n\n`+expressions.filter(e=>e.type===group).map(e=>`- **${e.id}｜${e.theme}：** **【原创】** ${e.text}`).join('\n'));
daily.push(`## 四、传统表达与灵活迁移\n\n### 复习更新：“治国有常，而利民为本。”\n\n- **核验来源：** [共产党员网“典”读二十大](https://www.12371.cn/2022/11/11/ARTI1668123327822239.shtml)，2022-11-11。典籍为《淮南子》。\n- **大白话：** 治理办法可以因事调整，最终要看有没有让百姓得到实实在在的好处。\n- **适用主题：** 公共服务、基层治理、数字普惠、便民利民。\n- **原创例句：** “治国有常，而利民为本。”办事大厅是不是更方便，不能只看机器添了多少，还要看不会用手机的老人是否仍能找到人、问明白、办成事。\n- **边界：** 不是“只要出发点为民就可以不守程序”；引用后仍需说明具体机制和合法边界。\n- **不入脑时这样练：** 合上原句，先说“老百姓办成事才算好”，再用自己的例子解释，最后还原典籍短句。不新增未经核验的名人名言。\n\n## 五、权威论述（Q283—Q284）`);
for(const q of authorities)daily.push(`### ${q.id}｜${q.title}\n\n- **原话节引：** “${q.quote}”\n- **场合与日期：** ${q.who}。\n- **官方原始链接：** [新华社原文](${q.url})。\n- **释义（原创）：** ${q.meaning}\n- **原创迁移示范：** ${q.example}\n- **使用边界：** ${q.boundary}`);
daily.push(`## 六、两则原创论证段\n\n### 段落一｜服务便利不能只有一个入口\n\n**【原创】** 提高公共服务效率，应让技术帮助人，而不能让人迁就技术。线上预约和自助办理能够节省时间，但不同群体的操作能力与生活节奏并不相同。如果只增加设备、撤去人工，表面上流程统一了，部分群众反而会被挡在门外。可先调查高频事项与使用困难，再保留人工咨询、电话指引和必要帮办，为异地群众优化在线流程，并根据退件原因持续改进。判断改革成效，应多问一问群众能否独立完成、是否需要反复跑腿、遇到异常有没有人回应，让效率与公平共同体现在办成一件件事上。\n\n### 段落二｜整治之后，更要接好教育支持\n\n**【原创】** 预防青少年危险骑行，应把现场处置与长期支持相衔接。危险行为必须及时制止，具体违法事实应依法处理；但如果非法改装来源没有查清、网络炫技仍有流量奖励、个人成长需求无人回应，简单处置之后仍可能反复。可由有关部门依法协同排查，督促平台及时处理危险行为传播，推动学校、家庭与社会力量共同开展教育和帮助。既守住公共安全和法律边界，也让青少年获得健康活动、正向交往与必要支持，才能减少从一次跟风走向长期失范的风险。\n\n## 七、写作实战：先提纲，后整段\n\n### 20分钟任务｜开放社区活动室\n\n**原创模拟材料：** 社区有一间活动室，白天老人想读报，晚上年轻人想自习，周末家长想开展亲子活动。物业担心噪声和设备损耗；志愿者愿意参与但难以长期每日值守。社区有固定维护预算，不能立刻扩建。\n\n**作答要求：** 以社区工作人员身份提出三项改进建议，200字以内。每一项都要回应材料中的一处具体困难。先独立写，再核对下面清单。\n\n**原创参考思路：** 调查需求、分时使用；明确安静和活动时段并公开规则；明确维护责任、预算用途与志愿排班，持续收集反馈。不虚构社区有权强制所有商户出资，不承诺永久免费扩建。\n\n**自评清单：** ①有没有错时安排；②有没有回应噪声与维护；③有没有照顾志愿力量可持续；④有没有无依据承诺。每项仅用于自查，不代表官方分值。\n\n## 八、今日必背\n\n### 3个标题\n\n1. 让有限空间承载更好的公共服务\n2. 从一次处置走向持续守护\n3. 让开放创新与责任安排同行\n\n### 5条表达\n\n${[1041,1044,1046,1050,1054].map(n=>{const e=expressions.find(v=>v.id===`G${n}`);return `- **${e.id}：** ${e.text}`}).join('\n')}\n\n### 1个案例\n\n- **上海社区服务空间：** 把不同人群的时间、功能需要与公共空间使用连接起来，并吸收居民等力量参与。记“需求—安排—责任—反馈”，不必死背地名和未经核验的数字。\n\n### 1条权威论述\n\n- **Q283：** “节水优先、空间均衡、系统治理、两手发力”。先说清四个词如何对应治理问题，再默写短句。\n\n## 九、25分钟学习与复盘\n\n1. **8分钟找结构：** 每篇只写一句“问题是什么、作者提出什么思路”。\n2. **5分钟闭卷回忆：** 复述G1044、G1046、G1050，不要求第一次逐字一致，但须保留条件与动作。\n3. **8分钟迁移：** 用“乡村便民服务”替换“社区活动室”，写100字，检查有没有还残留不适用的场景。\n4. **4分钟纠错：** 记录“我漏了什么—材料哪句话提醒过我—下次如何发现”，只改一处最重要的问题。\n\n### 到期间隔复习\n\n- **第1、3、7天目标：11月4日、11月2日、10月29日**：目前没有这些日期的日刊，不伪造补档；合并回顾[10月28日](2026-10-28.md)，比较“接诉即办”与今日“服务空间”怎样找到共性问题。\n- **第14天目标10月22日**：当日无日刊，可就近回顾[10月24日](2026-10-24.md)的公共服务材料，不重读全部文章。\n- **本期后续复习日：** 11月6日、11月8日、11月12日、11月19日、12月5日。默认1、3、7、14、30天；忘记时次日再练。\n- **检验是否学会：** 换一个场景仍能解释观点，且能从材料选出支持它的事实，才有比原文背熟更强的练习证据。\n\n## 十、资料边界与本期核验\n\n- 本期仅新增2026-11-05，保留既有日刊及各日期档案，不补写10月29日至11月4日。\n- 原始报道与原创讲解分开；G1041—G1055均为学习性原创，Q283—Q284为已核出处的短节引。\n- 5篇精读正文均已读取；人民日报页面通过HTTP原站读取，光明网内容正确处理gzip，新华社原文独立读取。半月谈一篇使用权威媒体转载并明确转载身份。\n- 科技评论的建议不写成法律规定，公安报道不作为具体处罚法条，展会展示不作为全面应用效果的证明。\n- 这次加入“审题—材料取证—格纸写作—对照改稿”训练，国考、川渝省考、事业综应和军队文职岗位写作分别使用，不能混成一种考试。`);
const dayText=daily.join('\n\n')+'\n';
const articleIndex=`\n\n## ${date} 新增精读来源\n\n`+articles.map(a=>{const s=source(a.id);return `### ${date}｜${s.title}\n\n- **原文：** [${s.publisher}](${s.url})\n- **作者与发布：** ${s.publisher}；${s.publishedAt}\n- **收录类别：** 精读；收录日期${date}\n- **主旨内容：** ${a.summary}\n- **可用方向：** ${a.themes}\n- **迁移提醒：** ${a.boundary}\n- **每日链接：** [${date}](每日积累/${date}.md)`}).join('\n\n')+'\n';
const themeIndex=`\n\n## ${date} 新增主题与案例\n\n`+articles.map(a=>{const s=source(a.id);return `### ${date}｜${a.themes}\n\n- **核心原文：** [${s.title}](${s.url})\n- **案例与分析（原创）：** ${a.method}\n- **使用边界：** ${a.boundary}\n- **每日链接：** [${date}](每日积累/${date}.md)`}).join('\n\n')+'\n';
const expressionIndex=`\n\n## ${date} 新增原创表达（G1041—G1055）\n\n`+expressions.map(e=>`- **${e.id}｜${e.type}｜${e.theme}：** **【原创】** ${e.text}｜[每日链接](每日积累/${date}.md)`).join('\n')+`\n\n### ${date}｜传统表达复习迁移\n\n“治国有常，而利民为本。”的出处核验与公共服务新用例见[本日第四节](每日积累/${date}.md)。这是旧表达的复习迁移，不伪装成新发现的典籍语句。\n`;
const authorityIndex=`\n\n## ${date} 新增权威论述（Q283—Q284）\n\n`+authorities.map(q=>`### ${q.id}｜${q.title}｜${date}\n\n- **原话节引：** “${q.quote}”\n- **场合与日期：** ${q.who}。\n- **官方原始链接：** [新华社原文](${q.url})\n- **释义（原创）：** ${q.meaning}\n- **原创迁移示范：** ${q.example}\n- **使用边界：** ${q.boundary}\n- **每日链接：** [${date}](每日积累/${date}.md)`).join('\n\n')+'\n';

const additions={'文章来源索引.md':articleIndex,'主题索引.md':themeIndex,'金句与传统表达索引.md':expressionIndex,'权威论述索引.md':authorityIndex};
const outputs=new Map([[path.join(root,'每日积累',`${date}.md`),dayText]]);
for(const [file,added] of Object.entries(additions)){const p=path.join(root,file);const old=fs.readFileSync(p,'utf8');if(old.includes(`## ${date} 新增`))throw new Error(`Already contains date: ${file}`);outputs.set(p,old.replace(/\s*$/,'')+added);}
if(fs.existsSync(path.join(root,'每日积累',`${date}.md`)))throw new Error('Daily already exists; review before replacing');
for(const a of articles){const s=source(a.id);for(const file of fs.readdirSync(path.join(root,'每日积累')).filter(f=>f.endsWith('.md'))){if(fs.readFileSync(path.join(root,'每日积累',file),'utf8').includes(s.url))throw new Error(`Duplicate article from ${file}: ${s.title}`);}}
for(const [p,text] of outputs){if(text.includes('\ufffd')||text.includes('\0'))throw new Error(`Encoding issue ${p}`);if(!text.includes(date))throw new Error('Date missing');}
const backup=path.resolve('output/backups/shenlun-20261105-'+Date.now());fs.mkdirSync(backup,{recursive:true});
const backups=[];
try{
 for(const [p,text] of outputs){const existed=fs.existsSync(p);const old=existed?fs.readFileSync(p):null;if(existed)fs.writeFileSync(path.join(backup,path.basename(p)),old);backups.push({p,old});fs.writeFileSync(p+'.nov5.tmp',text,'utf8');}
 for(const [p] of outputs)fs.renameSync(p+'.nov5.tmp',p);
 for(const [p,text] of outputs)if(fs.readFileSync(p,'utf8')!==text)throw new Error(`Readback mismatch ${p}`);
}catch(error){for(const {p,old} of backups)if(old)fs.writeFileSync(p,old);else if(fs.existsSync(p))fs.unlinkSync(p);throw error;}
const digest=crypto.createHash('sha256').update(dayText).digest('hex');
console.log(JSON.stringify({date,articles:articles.length,expressions:expressions.length,authorities:authorities.length,bytes:Buffer.byteLength(dayText),sha256:digest,backup,files:[...outputs.keys()]},null,2));
